// PROTOTYPE — selected layout A, in-memory interactions, never gateway I/O.
const clone = x => JSON.parse(JSON.stringify(x));
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={A:'树形检查器'};
const seed={version:1,log:{level:'info',file:''},ui:{enabled:false,listen:'127.0.0.1:8090'},models:[{id:'m1',kind:'model',name:'产线共享模型',persistence:'memory',path:''}],gateways:[{id:'g1',kind:'gateway',name:'产线采集',upstreams:[{id:'u1',kind:'upstream',name:'TCP 主站入口',type:'tcp',address:'0.0.0.0:15020',device:'',baud:'19200',bits:'8',parity:'N',stop:'1',timeout:'1s',pause:'0s',rs485:false,before:'0ms',after:'0ms'}],downstreams:[{id:'d1',kind:'downstream',name:'温控器',type:'rtu',slave_ids:'1-4',address:'192.168.10.40:502',device:'/dev/ttyUSB0',baud:'19200',bits:'8',parity:'E',stop:'1',timeout:'1s',pause:'20ms',rs485:false,before:'0ms',after:'0ms'},{id:'d2',kind:'downstream',name:'模拟从站',type:'local',slave_ids:'10',ref:'m1',address:'',device:'',baud:'9600',bits:'8',parity:'N',stop:'1',timeout:'1s',pause:'0s',rs485:false,mappings:[]},{id:'d3',kind:'downstream',name:'数据注入',type:'injector',slave_ids:'20',ref:'m1',address:'',device:'',baud:'9600',bits:'8',parity:'N',stop:'1',timeout:'1s',pause:'0s',rs485:false,mappings:[{source:'holding_registers',start:'0',count:'16',target:'input_registers',dest:'100'}]}]},{id:'g2',kind:'gateway',name:'包装线转发',upstreams:[{id:'u2',kind:'upstream',name:'包装线入口',type:'tcp',address:'127.0.0.1:15021',device:'',baud:'9600',bits:'8',parity:'N',stop:'1',timeout:'1s',pause:'0s',rs485:false}],downstreams:[{id:'d4',kind:'downstream',name:'包装 PLC',type:'tcp',slave_ids:'30-35',address:'192.168.10.60:502',device:'',baud:'9600',bits:'8',parity:'N',stop:'1',timeout:'1s',pause:'0s',rs485:false}]}]};
let variant=new URLSearchParams(location.search).get('variant')||'A';if(!names[variant])variant='A';
let state={draft:clone(seed),saved:clone(seed),running:clone(seed),disk:clone(seed),lastGood:clone(seed),runtime:'运行中',selected:'overview',group:'gateway',query:'',filter:'all',mode:'visual',diff:false,diffTab:'draft',checked:[],history:[],future:[],transaction:null,stage:0,conflict:false,recovery:null,failNext:false,modal:null,back:[],showState:false,notice:'',collapsed:{}};
const app=document.querySelector('#app'), modalRoot=document.querySelector('#modal');
const all=(cfg=state.draft)=>[{id:'global',kind:'global',name:'全局运行设置',...cfg.log},...cfg.models,...cfg.gateways.flatMap(g=>[g,...g.upstreams.map(o=>({...o,gateway:g.id})),...g.downstreams.map(o=>({...o,gateway:g.id}))])];
const obj=(id,cfg=state.draft)=>all(cfg).find(o=>o.id===id);
function mutable(id,cfg=state.draft){if(id==='global')return cfg;for(const o of cfg.models)if(o.id===id)return o;for(const g of cfg.gateways){if(g.id===id)return g;for(const o of [...g.upstreams,...g.downstreams])if(o.id===id)return o;}return null;}
const gatewayName=o=>obj(o.gateway)?.name||'—';
const kindName=k=>({gateway:'网关',upstream:'上游',downstream:'下游',model:'模拟模型',global:'常规'}[k]);
const typeName=t=>({tcp:'Modbus TCP',rtu:'串口 RTU','rtu-over-tcp':'RTU-over-TCP',local:'本地模拟 · local',injector:'数据注入 · injector'}[t]||t);
const endpoint=o=>['local','injector'].includes(o.type)?obj(o.ref)?.name||'未选择模型':o.type==='rtu'?o.device:o.address||'—';
const badge=(s,k='')=>`<span class="badge ${k}">${esc(s)}</span>`;
function flatten(cfg){let m={};for(const o of all(cfg)){let copy={...o};delete copy.upstreams;delete copy.downstreams;delete copy.gateway;m[o.id]=copy;}return m;}
function differences(a,b){const x=flatten(a),y=flatten(b),out=[];for(const id of new Set([...Object.keys(x),...Object.keys(y)])){const old=x[id],next=y[id];if(!old||!next){out.push({id,label:(next||old).name,key:next?'新增':'删除',old:old?'存在':'',new:next?'存在':''});continue;}for(const key of new Set([...Object.keys(old),...Object.keys(next)])){if(JSON.stringify(old[key])!==JSON.stringify(next[key]))out.push({id,label:next.name,key,old:old[key],new:next[key]});}}for(const key of ['log','ui'])if(JSON.stringify(a[key])!==JSON.stringify(b[key]))out.push({id:'global',label:'全局运行设置',key,old:a[key],new:b[key]});return out;}
const draftDiff=()=>differences(state.saved,state.draft),pendingDiff=()=>differences(state.running,state.saved);
function ids(text){if(!text.trim())return [];let set=new Set();for(const item of text.split(',')){const m=item.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error('使用 1、1,3 或 10-20 的格式');let a=Number(m[1]),b=m[2]===undefined?a:Number(m[2]);if(a>b||b>255)throw Error('ID 范围为 0–255，范围起点不能大于终点');for(let i=a;i<=b;i++)set.add(i);}return [...set].sort((a,b)=>a-b);}
function problems(cfg=state.draft){let p=[];const add=(id,field,text)=>p.push({id,field,text});const address=v=>/^(?:\[[^\]]+\]|[^:\s]+|):\d+$/.test(v)&&Number(v.slice(v.lastIndexOf(':')+1))<=65535;
 const listeners=new Map();for(const g of cfg.gateways){if(!g.upstreams.length)add(g.id,'upstreams','请添加至少一个上游');if(!g.downstreams.length)add(g.id,'downstreams','请添加至少一个下游');const owners=new Map();for(const o of [...g.upstreams,...g.downstreams]){if(['tcp','rtu-over-tcp'].includes(o.type)&&!address(o.address))add(o.id,'address',`${o.name}：地址应为主机:端口`);if(o.kind==='upstream'&&['tcp','rtu-over-tcp'].includes(o.type)){if(listeners.has(o.address))add(o.id,'address',`监听地址与 ${listeners.get(o.address)} 重复`);listeners.set(o.address,o.name);}if(o.type==='rtu'){if(!o.device)add(o.id,'device','请输入串口设备路径');if(!/^\d+$/.test(o.baud)||Number(o.baud)<=0)add(o.id,'baud','波特率必须为正整数');for(const k of ['timeout','pause'])if(!/^\d+(?:\.\d+)?(?:ms|s|m|h)$/.test(o[k]))add(o.id,k,'请输入非负时长，例如 500ms 或 2s');}if(o.kind==='downstream'){try{let parsed=ids(o.slave_ids);if(['local','injector'].includes(o.type)&&parsed.length!==1)add(o.id,'slave_ids','local / injector 必须指定一个 Slave ID');if(!parsed.length&&g.downstreams.length>1)add(o.id,'slave_ids','多个下游时必须明确 Slave ID');for(const id of parsed){if(owners.has(id))add(o.id,'slave_ids',`Slave ID ${id} 与 ${owners.get(id)} 冲突`);owners.set(id,o.name);}}catch(e){add(o.id,'slave_ids',e.message);}if(['local','injector'].includes(o.type)&&!cfg.models.some(m=>m.id===o.ref))add(o.id,'ref','请选择存在的模拟模型');if(o.type==='injector'){if(!o.mappings?.length)add(o.id,'mappings','注入入口需要至少一条映射');(o.mappings||[]).forEach((m,i)=>{let start=Number(m.start),count=Number(m.count),dest=Number(m.dest);if(![m.start,m.count,m.dest].every(v=>/^\d+$/.test(v))||count<1||start+count>65536||dest+count>65536)add(o.id,`mapping.${i}.count`,`映射 ${i+1}：数量必须为正整数，区间不得超过 65535`);});}}}}
 const ranges=[];for(const o of all(cfg).filter(x=>x.type==='injector'))for(const [i,m]of(o.mappings||[]).entries()){for(const prev of ranges)if(prev.ref===o.ref&&prev.target===m.target&&Number(m.dest)<prev.end&&Number(m.dest)+Number(m.count)>prev.start)add(o.id,`mapping.${i}.dest`,`目标区间与 ${prev.name} 重叠（共享模型 ${obj(o.ref,cfg)?.name}）`);ranges.push({ref:o.ref,target:m.target,start:Number(m.dest),end:Number(m.dest)+Number(m.count),name:o.name});}
 for(const m of cfg.models){if(!m.name.trim())add(m.id,'name','模型名称不能为空');if(m.persistence!=='memory'&&!m.path)add(m.id,'path','请输入持久化路径');if(cfg.models.some(x=>x.id!==m.id&&x.name===m.name))add(m.id,'name','模拟模型名称重复');}return p;}
function record(){state.history.push(clone(state.draft));if(state.history.length>100)state.history.shift();state.future=[];}
function edit(id,key,value){const target=mutable(id);if(!target)return;if(key==='name'&&target.kind==='model'){if(!state.transaction)state.transaction={id,before:clone(state.draft)};}else record();if(key.startsWith('mapping.')){const[,i,k]=key.split('.');target.mappings[Number(i)][k]=value;}else if(key.startsWith('log.')||key.startsWith('ui.')){const[a,b]=key.split('.');target[a][b]=value;}else target[key]=value;render();}
function finishTransaction(cancel=false){if(!state.transaction)return true;if(cancel)state.draft=state.transaction.before;else {if(problems().some(p=>p.id===state.transaction.id)){toast('请先修复当前关联编辑中的问题');return false;}state.history.push(state.transaction.before);state.future=[];}state.transaction=null;return true;}
function navigate(id){if(obj(id)?.kind==='model')state.collapsed.models=false;const parent=obj(id)?.gateway;if(parent)state.collapsed[parent]=false;if(variant==='C'){const o=obj(id);if(o?.kind==='gateway'||o?.kind==='upstream')state.stage=1;if(o?.kind==='downstream')state.stage=1;if(o?.kind==='model')state.stage=2;}if(state.selected!==id)state.back.push(state.selected);state.selected=id;render();}
function statuses(id){return `${problems().some(p=>p.id===id)?badge('有问题','err'):''}${draftDiff().some(p=>p.id===id)?badge('未保存','warn'):''}${pendingDiff().some(p=>p.id===id)?badge('待应用','warn'):''}`;}
function filtered(kind=state.group){return all().filter(o=>o.kind===kind).filter(o=>{const hay=JSON.stringify(o)+' '+(o.kind==='gateway'?JSON.stringify(mutable(o.id)):'')+' '+gatewayName(o)+' '+kindName(o.kind)+' '+({baud:'波特率 baud_rate',device:'串口',slave_ids:'从站 ID',parity:'校验位',timeout:'响应超时'}[state.query]||'');let matches=!state.query||hay.toLowerCase().includes(state.query.toLowerCase())||(o.type==='rtu'&&/波特率|baud_rate|校验位|数据位|响应超时/.test(state.query));let f=state.filter;return matches&&(f==='all'||f==='error'&&problems().some(p=>p.id===o.id)||f==='dirty'&&draftDiff().some(p=>p.id===o.id)||f==='pending'&&pendingDiff().some(p=>p.id===o.id)||f==='unused'&&o.kind==='model'&&!all().some(x=>x.ref===o.id));});}
function button(label,action,cls='',disabled=false,attrs=''){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''} ${attrs}>${label}</button>`;}
function primary(){if(state.runtime==='应用中')return button('正在应用…','apply','primary',true);if(problems().length)return button(`修复 ${problems().length} 处问题`,'issues','primary');if(draftDiff().length)return button('保存并应用','save-apply','primary');if(state.runtime==='已停止'||state.runtime==='应用失败')return button('启动网关','apply','primary');if(pendingDiff().length)return button('应用已保存配置','apply','primary');return button('配置已同步','apply','',true);}
function header(){let errors=problems(),dirty=draftDiff().length,pending=pendingDiff().length;return `<div class="menu"><span>文件</span><span>编辑</span><span>查看</span><span>网关</span><span>ModMux</span></div><div class="module"><span class="muted">联动监视</span><strong>配置编辑</strong></div><header class="filehead"><div><div class="flex wrap"><span class="filename">factory-floor.yaml</span>${badge('v1')}${errors.length?badge(`${errors.length} 处问题`,'err'):''}${dirty?badge(`${dirty} 处未保存`,'warn'):''}${pending?badge(`${pending} 处待应用`,'warn'):''}${!dirty&&!pending?badge('文件与运行一致'):''}</div><div class="filemeta" title="/Users/engineer/Projects/factory/factory-floor.yaml">/Users/engineer/Projects/factory/factory-floor.yaml</div></div><div class="flex"><div class="seg">${button('可视化','visual',state.mode==='visual'?'active':'')}${button('YAML','yaml',state.mode==='yaml'?'active':'')}</div>${button('变更 '+(dirty+pending||''),'diff',state.diff?'active':'')}${dirty?button('仅保存','save','',errors.length>0):''}${primary()}</div></header><div class="searchbar"><input id="search" placeholder="搜索对象、地址或字段，如 波特率" value="${esc(state.query)}" aria-label="搜索配置"><select id="filter" aria-label="状态筛选"><option value="all">全部状态</option><option value="error">有问题</option><option value="dirty">未保存</option><option value="pending">待应用</option>${state.group==='model'?'<option value="unused">无引用模型</option>':''}</select><div class="grow"></div>${button('返回','back','',!state.back.length)}${button('撤销','undo','',!state.history.length&&!state.transaction)}${button('重做','redo','',!state.future.length)}</div>`;}
// Tree icons share a 20px grid and inherit semantic colors from design tokens.
function treeIcon(kind){
 const shapes={
  upstream:'<rect x="7" y="6" width="6" height="8" rx="1"/><path d="M1 10h6M4 7l3 3-3 3M13 10h6"/>',
  downstream:'<rect x="7" y="6" width="6" height="8" rx="1"/><path d="M1 10h6M13 10h6M16 7l3 3-3 3"/>',
  model:'<path d="m10 3 7 4-7 4-7-4 7-4Zm-7 8 7 4 7-4M3 15l7 4 7-4"/>',
  settings:'<path d="M3 5h14M3 10h14M3 15h14"/><rect x="6" y="3" width="3" height="4" rx="1" fill="var(--soft)"/><rect x="11" y="8" width="3" height="4" rx="1" fill="var(--soft)"/><rect x="5" y="13" width="3" height="4" rx="1" fill="var(--soft)"/>',
  gateway:'<rect x="5" y="5" width="10" height="10" rx="2"/><path d="M2 8h3m-3 4h3m10-4h3m-3 4h3M8 8h4m-4 4h4"/>',
  overview:'<rect x="3" y="3" width="5" height="5" rx="1"/><rect x="12" y="3" width="5" height="5" rx="1"/><rect x="3" y="12" width="5" height="5" rx="1"/><rect x="12" y="12" width="5" height="5" rx="1"/>',
  chevron:'<path d="m6 8 4 4 4-4"/>'
 };
 return `<svg class="tree-icon icon-${kind}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${shapes[kind]||shapes.model}</svg>`;
}
function leafRow(o,depth=0){return `<button class="tree-row ${state.selected===o.id?'active':''}" style="--depth:${depth}" data-select="${o.id}" title="${kindName(o.kind)} · ${esc(o.name)}" aria-label="${kindName(o.kind)} ${esc(o.name)}"><span class="tree-slot" aria-hidden="true"></span>${treeIcon(o.kind)}<span class="name">${esc(o.name)}</span><span class="tree-status">${problems().some(p=>p.id===o.id)?badge('!','err'):draftDiff().some(p=>p.id===o.id)?badge('•','warn'):''}</span></button>`;}
function sidebar(){return `<nav class="sidebar" aria-label="配置对象">${button('<span class="tree-slot"></span>'+treeIcon('overview')+'<span class="name">网关总览</span>','overview',`tree-row ${state.selected==='overview'?'active':''}`)}<div class="nav-label flex spread"><span>网关与链路</span>${button('＋','new-gateway','nav-add',false,'title="新建网关" aria-label="新建网关"')}</div>${state.draft.gateways.map(g=>{const open=!state.collapsed[g.id]||!!state.query;return `<div class="tree-row gateway-row ${state.selected===g.id?'active':''}"><button class="tree-toggle ${open?'':'collapsed'}" data-action="toggle-gateway" data-gateway="${g.id}" aria-label="${open?'收起':'展开'} ${esc(g.name)}" aria-expanded="${open}">${treeIcon('chevron')}</button><button class="tree-object" data-select="${g.id}" title="网关 · ${esc(g.name)}">${treeIcon('gateway')}<strong class="name">${esc(g.name||'未命名网关')}</strong></button></div>${open?`<div class="tree-children">${[...g.upstreams,...g.downstreams].filter(o=>!state.query||JSON.stringify(o).toLowerCase().includes(state.query.toLowerCase())||filtered(o.kind).some(x=>x.id===o.id)).map(o=>leafRow(o,1)).join('')}</div>`:''}`;}).join('')}<div class="nav-label flex spread"><span>模拟模型</span>${button('＋','new-model','nav-add',false,'title="新建模拟模型" aria-label="新建模拟模型"')}</div><div class="tree-row ${state.selected==='models'?'active':''}"><button class="tree-toggle ${state.collapsed.models?'collapsed':''}" data-action="toggle-models" aria-label="${state.collapsed.models?'展开':'收起'}模拟模型" aria-expanded="${!state.collapsed.models}">${treeIcon('chevron')}</button><button class="tree-object" data-action="models">${treeIcon('overview')}<span class="name">模拟模型总览</span></button></div>${!state.collapsed.models?`<div class="tree-children">${state.draft.models.map(m=>leafRow(m,1)).join('')}</div>`:''}<div class="nav-label">运行设置</div>${button('<span class="tree-slot"></span>'+treeIcon('settings')+'<span class="name">全局运行设置</span>','global',`tree-row ${state.selected==='global'?'active':''}`)}</nav>`;}

function field(o,key,label,options=null,hint='',wide=false){let val=key.includes('.')?(key.startsWith('mapping.')?o.mappings[Number(key.split('.')[1])][key.split('.')[2]]:key.split('.').reduce((a,k)=>a?.[k],o)):o[key];const issue=problems().find(p=>p.id===o.id&&p.field===key),old=obj(o.id,state.saved);let changed=old&&JSON.stringify(key.split('.').reduce((a,k)=>a?.[k],old))!==JSON.stringify(val);let control=options?`<select data-id="${o.id}" data-field="${key}" id="field-${o.id}-${key}">${options.map(v=>`<option value="${esc(typeof v==='string'?v:v[0])}" ${val===(typeof v==='string'?v:v[0])?'selected':''}>${esc(typeof v==='string'?v:v[1])}</option>`).join('')}</select>`:`<input class="${issue?'invalid':''}" data-id="${o.id}" data-field="${key}" id="field-${o.id}-${key}" value="${esc(val)}" ${key==='baud'?'list="baud-values"':''}>`;return `<div class="field ${wide?'wide':''} ${changed?'changed':''}"><label for="field-${o.id}-${key}">${esc(label)}</label>${control}${hint?`<small>${esc(hint)}</small>`:''}${issue?`<small class="error">${esc(issue.text)}</small>`:''}</div>`;}
function errorList(id){const p=problems().filter(p=>!id||p.id===id);return p.length?`<div class="error-list"><strong>${p.length} 处需要修复</strong>${p.map(x=>`<button class="link" data-focus="${x.id}|${x.field}">${esc(x.text)} ↗</button>`).join('')}</div>`:'';}
function objectDetail(id=state.selected){const o=obj(id);if(!o)return overview();if(o.kind==='global')return `<div class="detailhead"><div><h2>全局运行设置</h2><p class="subtitle">日志与高级命令行选项</p></div></div><section class="section"><h3>日志</h3><div class="fields">${field({...state.draft,id:'global'},'log.level','日志级别',['debug','info','warn','error'])}${field({...state.draft,id:'global'},'log.file','日志文件',null,'留空时输出到标准输出')}</div></section><details class="section"><summary>命令行运行设置</summary><div class="helper">管理 API 设置只作用于直接 CLI 运行。桌面管理连接由 sidecar 使用回环地址覆盖。</div><div class="fields">${field({...state.draft,id:'global'},'ui.listen','CLI 管理 API 监听地址')}</div></details>`;
 let title=`<div class="breadcrumbs">${o.gateway?`${esc(gatewayName(o))} / `:''}${kindName(o.kind)}</div><div class="detailhead"><div><h2>${esc(o.name||'未命名网关')}</h2><div class="flex wrap subtitle">${o.type?typeName(o.type):o.kind==='model'?'共享模拟数据模型':'按 Slave ID 路由请求'} ${statuses(o.id)}</div></div><div class="flex">${button('复制','copy-one')}${button('删除','delete-one','danger')}</div></div>`;
 if(state.transaction?.id===o.id)title+=`<div class="batch">关联编辑 ${button('完成编辑','finish','primary')}${button('放弃本次编辑','cancel-edit')}</div>`;
 if(o.kind==='gateway'){let g=mutable(o.id);return title+errorList(o.id)+`<section class="section"><div class="fields">${field(o,'name','网关名称')}</div></section><section class="section"><div class="flex spread"><h3>主站入口 · ${g.upstreams.length}</h3>${button('添加上游','add-upstream','',false,`id="field-${g.id}-upstreams"`)}</div>${g.upstreams.length?objectTable(g.upstreams.map(x=>({...x,gateway:g.id})),false):'<p class="subtitle">尚未配置主站入口。添加 TCP、RTU 或 RTU-over-TCP 上游。</p>'}</section><section class="section"><div class="flex spread"><h3>路由覆盖 · ${g.downstreams.length} 个下游</h3>${button('添加下游','add-downstream','',false,`id="field-${g.id}-downstreams"`)}</div>${g.downstreams.length?objectTable(g.downstreams.map(x=>({...x,gateway:g.id})),false):'<p class="subtitle">尚未配置路由目标。添加真实设备、local 或 injector 下游。</p>'}</section>`;}
 if(o.kind==='model'){let refs=all().filter(x=>x.ref===o.id);return title+errorList(o.id)+`<section class="section"><div class="fields">${field(o,'name','模型名称',null,'完成关联编辑后同步所有引用')}${field(o,'persistence','持久化类型',[['memory','memory · 重启清空'],['file','file · 文件存储'],['mmap','mmap · 映射文件'],['sql','sql · SQLite']])}${o.persistence!=='memory'?field(o,'path','持久化路径',null,'相对工程目录解析，不会随模型改名移动文件',true):''}</div>${o.persistence==='memory'?'<div class="helper">数据只保留在运行进程中。重启整个网关进程会清空所有 memory 模型。</div>':`<div class="helper mono">实际位置：${esc(o.path.startsWith('/')?o.path:'/Users/engineer/Projects/factory/'+o.path)}</div>`}</section><section class="section"><h3>使用方 · ${refs.length}</h3>${refs.length?objectTable(refs,false):'<p class="muted">暂无引用。模型可以保留，不影响保存。</p>'}</section>`;}
 let fields=field(o,'name',o.kind==='upstream'?'入口名称':'下游名称')+field(o,'type','协议',o.kind==='upstream'?['tcp','rtu','rtu-over-tcp']:['tcp','rtu','rtu-over-tcp','local','injector']);
 if(o.kind==='downstream')fields+=field(o,'slave_ids','从站 ID',null,'零到 255；支持列表与范围。local / injector 使用单一 ID');
 if(['tcp','rtu-over-tcp'].includes(o.type))fields+=field(o,'address',o.kind==='upstream'?'上游监听地址':'下游连接地址',null,o.kind==='upstream'?'本机绑定端口；例如 0.0.0.0:15020':'真实设备的主机与端口');
 if(['local','injector'].includes(o.type))fields+=`<div class="field wide">${field(o,'ref','共享模拟模型',[['','选择模拟模型'],...state.draft.models.map(m=>[m.id,m.name])],'多个入口引用同一模型时共享数据')}${button('新建并引用模型…','new-reference','link')}</div>`;
 let html=title+errorList(o.id)+`<section class="section"><h3>基本配置</h3><div class="fields">${fields}</div>${o.kind==='downstream'?routeHint(o):''}${o.type==='rtu-over-tcp'?'<div class="helper">传输完整 RTU 帧，包含 CRC；与使用 MBAP 头的 Modbus TCP 不同。</div>':''}${['local','injector'].includes(o.type)?`<div class="helper">${o.type==='local'?'业务入口按标准 Modbus 语义读写模型。':'注入入口把写请求映射到离散输入或输入寄存器，不提供真实设备连接。'} ${button('查看模型与使用方 ↗','open-model','link')}</div>`:''}</section>`;
 if(o.type==='rtu')html+=`<section class="section"><h3>串口通信</h3><div class="fields">${field(o,'device','串口设备',null,'可直接输入设备路径',true)}${field(o,'baud','波特率',null,'可输入自定义值，常用值仅为建议')}${field(o,'bits','数据位',['5','6','7','8'])}${field(o,'parity','校验位',[['N','无校验 N'],['E','偶校验 E'],['O','奇校验 O']])}${field(o,'stop','停止位',['1','2'])}${field(o,'timeout','响应超时',null,'例如 500ms、1s')}${field(o,'pause','请求间隔',null,'例如 0s、20ms')}</div><datalist id="baud-values"><option value="9600"><option value="19200"><option value="38400"><option value="115200"></datalist></section><section class="section"><label class="toggle-label"><input type="checkbox" data-id="${o.id}" data-field="rs485" ${o.rs485?'checked':''}> RS485 专用设置</label>${o.rs485?`<div class="fields" style="margin-top:12px">${field(o,'before','发送前 RTS 延迟')}${field(o,'after','发送后 RTS 延迟')}</div><small class="muted">实际硬件支持取决于系统和串口驱动。</small>`:''}</section>`;
 if(o.type==='injector')html+=`<section class="section"><div class="flex spread"><h3>写入映射 · 零基地址</h3>${button('＋ 映射','add-mapping')}</div><small class="muted">地址 0 不等同于设备手册的 40001；结束地址由起点和数量推导。</small>${(o.mappings||[]).map((m,i)=>`<div class="helper"><div class="flex spread"><strong>映射 ${i+1} · ${m.start}–${Number(m.start)+Number(m.count)-1} → ${m.dest}–${Number(m.dest)+Number(m.count)-1}</strong>${button('移除','remove-mapping','',false,`data-index="${i}"`)}</div><div class="fields">${field(o,`mapping.${i}.source`,'源表',['coils','holding_registers'])}${field(o,`mapping.${i}.target`,'目标表',[m.source==='coils'?'discrete_inputs':'input_registers'])}${field(o,`mapping.${i}.start`,'源起始地址')}${field(o,`mapping.${i}.count`,'数量')}${field(o,`mapping.${i}.dest`,'目标起始地址')}</div></div>`).join('')}</section>`;
 return html;}
function routeHint(o){try{const parsed=ids(o.slave_ids);return `<small class="muted">${parsed.length?'路由覆盖 '+parsed.join(', ')+' · 共 '+parsed.length+' 个 ID':'默认路由：接收未显式指定的从站请求；多下游时请指定 ID'}</small>`;}catch{return '';}}
function objectTable(objects,checks=true){return `<div class="table-scroll"><table><thead><tr>${checks?'<th style="width:28px"></th>':''}<th>名称 / 协议</th><th>端点 / 模型</th><th>Slave ID</th><th>状态</th></tr></thead><tbody>${objects.map(o=>`<tr>${checks?`<td><input type="checkbox" data-check="${o.id}" ${state.checked.includes(o.id)?'checked':''} aria-label="选择 ${esc(o.name)}"></td>`:''}<td><button class="link" data-select="${o.id}">${esc(o.name||'未命名网关')}</button><div class="caption muted">${o.type?typeName(o.type):o.kind==='model'?o.persistence:kindName(o.kind)}${o.gateway?' · '+esc(gatewayName(o)):''}</div></td><td class="mono">${esc(o.kind==='gateway'?`${o.upstreams.length} 上游 · ${o.downstreams.length} 下游`:o.kind==='model'?o.path||'内存':endpoint(o))}</td><td><span class="route-id mono">${esc(o.slave_ids||'—')}</span></td><td><div class="flex wrap">${statuses(o.id)||badge('已保存')}</div></td></tr>`).join('')}</tbody></table></div>`;}
function batchBar(){if(!state.checked.length)return '';const selected=state.checked.map(id=>obj(id)).filter(Boolean),visible=filtered(),hidden=selected.filter(o=>!visible.some(v=>v.id===o.id)).length;return `<div class="batch"><strong>已选择 ${selected.length} 项${hidden?' · '+hidden+' 项隐藏':''}</strong>${button('复制','batch-copy')}${selected.every(o=>o.kind==='downstream')?button('移动下游','batch-move'):''}${button('删除','batch-delete','danger')}${button('取消选择','clear-checks','link')}</div>`;}
function overview(){const kind=state.selected==='models'?'model':'gateway';state.group=kind;const list=filtered(kind),filteredEmpty=state.query||state.filter!=='all',label=kind==='model'?'新建模拟模型':'新建网关',action=kind==='model'?'new-model':'new-gateway';return `<div class="detailhead"><div><h2>${kindName(kind)}总览</h2><p class="subtitle">查看配置关系，选择对象后执行批量操作</p></div>${list.length||filteredEmpty?button(label,action):''}</div>${batchBar()}${list.length?objectTable(list):`<div class="empty"><h2>${filteredEmpty?'没有匹配对象':kind==='model'?'还没有模拟模型':'开始配置你的工程'}</h2><p>${filteredEmpty?'调整搜索词或清除筛选条件。':kind==='model'?'创建共享模型，再由 local 或 injector 下游引用。':'先创建网关，再添加主站入口和路由目标。'}</p>${button(filteredEmpty?'清除筛选':label,filteredEmpty?'clear-search':action,'primary')}</div>`}`;}

function diffPane(tab=state.diffTab){const list=tab==='draft'?draftDiff():pendingDiff();return `<h3>变更检查</h3><div class="seg">${button('待保存 '+draftDiff().length,'diff-draft',tab==='draft'?'active':'')}${button('待应用 '+pendingDiff().length,'diff-saved',tab==='saved'?'active':'')}</div><small class="muted">${tab==='draft'?'已保存文件 → 当前草稿':'实际运行 → 已保存文件'}</small>${list.length?list.map(d=>`<div class="diff-item"><button class="link" data-select="${d.id}">${esc(d.label)} ↗</button><div class="caption muted">${esc(d.key)}</div><pre class="minus">− ${esc(typeof d.old==='object'?JSON.stringify(d.old):d.old||'空')}</pre><pre class="plus">＋ ${esc(typeof d.new==='object'?JSON.stringify(d.new):d.new||'空')}</pre></div>`).join(''):'<div class="empty"><p>这个版本间没有变化。</p></div>'}<div class="helper"><strong>实际应用范围</strong><p>整个子进程重启；全部 ${state.running.gateways.length} 个运行中网关转发中断，所有 memory 模型数据清空。</p></div>${tab==='draft'&&list.length?button('放弃全部未保存修改','discard','danger'):''}`;}
function yaml(cfg=state.draft){const q=v=>JSON.stringify(v);let lines=['version: 1','log:',`  level: ${cfg.log.level}`,'simulations:'];for(const m of cfg.models)lines.push(`  - name: ${q(m.name)}`,'    persistence:',`      type: ${m.persistence}`,`      path: ${q(m.path)}`);lines.push('gateways:');for(const g of cfg.gateways){lines.push(`  - name: ${q(g.name)}`,'    upstreams:');for(const u of g.upstreams)lines.push(`      - type: ${u.type}`,`        ${u.type==='rtu'?'serial: {device: '+q(u.device)+', baud_rate: '+u.baud+'}':'tcp: {address: '+q(u.address)+'}'}`);lines.push('    downstreams:');for(const d of g.downstreams){lines.push(`      - name: ${q(d.name)}`,`        type: ${d.type}`,`        slave_ids: ${q(d.slave_ids)}`);if(['local','injector'].includes(d.type))lines.push(`        simulation: {ref: ${q(cfg.models.find(m=>m.id===d.ref)?.name||'')}}`);else if(d.type==='rtu')lines.push('        serial:',`          device: ${q(d.device)}`,`          baud_rate: ${d.baud}`,`          data_bits: ${d.bits}`,`          parity: ${q(d.parity)}`,`          stop_bits: ${d.stop}`,`          timeout: ${d.timeout}`,`          rqst_pause: ${d.pause}`);else lines.push(`        tcp: {address: ${q(d.address)}}`);}}return lines.join('\n');}
function yamlPane(){return `<article class="detail yaml-pane"><div class="detailhead"><div><h2>YAML 配置预览</h2><p class="subtitle">当前草稿的关键配置投影</p></div>${button('复制文本','copy-yaml')}</div><textarea class="yaml mono" readonly aria-label="YAML 预览">${esc(yaml())}</textarea></article>`;}
function VariantA(){return `<main class="workspace">${state.mode==='visual'?sidebar():''}${state.mode==='yaml'?yamlPane():`<article class="detail">${['overview','models'].includes(state.selected)?overview():objectDetail()}</article>`}${state.diff?`<aside class="inspector">${diffPane()}</aside>`:''}</main>`;}
function render(){const focus=document.activeElement?.id;let content=VariantA();let notice=state.conflict?`<div class="notice error"><span>磁盘文件已被其他程序修改。草稿保留，保存已暂停。</span>${button('查看并合并','conflict')}</div>`:state.recovery?`<div class="notice"><span>发现未保存草稿，可恢复后继续编辑。</span><div class="flex">${button('恢复草稿','restore-draft')}${button('丢弃','drop-recovery')}</div></div>`:state.runtime==='应用失败'?`<div class="notice error"><span>启动失败：监听地址被占用。已保存配置和草稿保留。</span>${button('运行最近成功配置','rollback')}</div>`:'';app.innerHTML=header()+notice+content+`<footer class="statusbar"><span>${esc(state.runtime)}${state.runtime==='运行中'?' · 管理连接正常':''}</span><span>草稿 ${draftDiff().length} 处变更 · 待应用 ${pendingDiff().length} 处 · 网关 ${state.draft.gateways.length}</span></footer>`;document.querySelector('#filter').value=state.filter;document.querySelector('#variant-name').textContent=variant+' · '+names[variant];if(notice)document.querySelector('.workspace').style.height='calc(100dvh - 272px)';if(state.showState)renderState();if(focus){const e=document.getElementById(focus);if(e)e.focus({preventScroll:true});}window.prototypeState=state;}
function renderState(){const panel=document.querySelector('#state-panel');panel.hidden=!state.showState;panel.innerHTML=`<div class="flex spread"><strong>内存状态 · ${variant}</strong>${button('关闭','state')}</div><pre>${esc(JSON.stringify({variant,runtime:state.runtime,selected:state.selected,transaction:state.transaction?.id||null,conflict:state.conflict,history:state.history.length,draftToSaved:draftDiff(),savedToRunning:pendingDiff(),draft:state.draft,saved:state.saved,running:state.running,disk:state.disk},null,2))}</pre>`;}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),4000);}
let previousFocus;
function openModal(type,body,large=false){previousFocus=document.activeElement;state.modal=type;app.inert=true;document.querySelector('#prototype-bar').inert=true;document.querySelector('#state-panel').inert=true;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="dialog ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${body}</section></div>`;modalRoot.querySelector('input,select,button')?.focus();}
function closeModal(){state.modal=null;modalRoot.innerHTML='';app.inert=false;document.querySelector('#prototype-bar').inert=false;document.querySelector('#state-panel').inert=false;previousFocus?.focus();}
function save(){if(!finishTransaction())return false;if(problems().length){toast('请修复问题后保存');return false;}if(state.conflict||JSON.stringify(state.disk)!==JSON.stringify(state.saved)){showConflict();return false;}state.saved=clone(state.draft);state.disk=clone(state.saved);render();toast('已保存；运行配置保持原样。');return true;}
function requestApply(){if(draftDiff().length){toast('请先保存或放弃未保存修改');return;}if(problems(state.saved).length){toast('已保存配置仍存在问题');return;}openModal('apply',`<h2 id="dialog-title">${state.runtime==='已停止'?'启动':'应用已保存配置'}</h2><p>本次会使用 <strong>factory-floor.yaml</strong> 中已保存的配置。</p><div class="impact"><strong>整个网关进程将重启</strong><p>全部 ${state.running.gateways.length} 个运行中网关转发中断；所有 memory 模型的数据清空。</p></div><p class="muted">取消后已保存文件保留，仍可稍后应用。</p><label class="toggle-label"><input id="fail-next" type="checkbox" ${state.failNext?'checked':''}> 启动结果：监听失败</label><footer>${button('取消','cancel')}${button('确认应用','confirm-apply','primary')}</footer>`);}
function showConflict(){state.conflict=true;render();openModal('conflict',`<h2 id="dialog-title">外部修改 · 核对三个版本</h2><p>保留当前草稿，将最新磁盘内容设为基线后手动合并。</p><div class="three-cols">${[['编辑基线',state.saved],['最新磁盘',state.disk],['当前草稿',state.draft]].map(([t,c])=>`<section><h3>${t}</h3><pre>${esc(yaml(c))}</pre></section>`).join('')}</div><p class="muted">重新基准化不会覆盖草稿，也不会自动保存。重新保存时再次检查磁盘版本。</p><footer>${button('取消','cancel')}${button('复制草稿','copy-yaml')}${button('保留草稿，更新基线','rebase','primary')}</footer>`,true);}
function scenario(value){closeModal();state.draft=clone(seed);state.saved=clone(seed);state.running=clone(seed);state.disk=clone(seed);state.lastGood=clone(seed);Object.assign(state,{runtime:'运行中',history:[],future:[],transaction:null,checked:[],selected:'overview',group:'gateway',filter:'all',query:'',diff:false,conflict:false,recovery:null,failNext:false,stage:0});if(value==='three'){mutable('d1',state.saved).baud='38400';state.disk=clone(state.saved);state.draft=clone(state.saved);mutable('d1').baud='57600';state.selected='d1';state.diff=true;}if(value==='invalid'){mutable('d2').slave_ids='3';state.selected='d2';}if(value==='external'){mutable('d1').baud='38400';mutable('d4',state.disk).address='192.168.10.99:502';state.conflict=true;state.selected='d1';}if(value==='failed'){state.saved.gateways[0].upstreams[0].address='0.0.0.0:502';state.draft=clone(state.saved);state.disk=clone(state.saved);state.runtime='应用失败';}if(value==='stopped')state.runtime='已停止';if(value==='recovery'){state.recovery=clone(seed);mutable('d1',state.recovery).baud='57600';}if(value==='empty'){state.draft.gateways=[];state.draft.models=[];state.saved=clone(state.draft);state.running=clone(state.draft);state.disk=clone(state.draft);state.runtime='已停止';}if(variant==='C'&&obj(state.selected)?.gateway)state.stage=1;document.querySelector('#scenario').value=value;render();}

let bulkIds=[],bulkMode='',uid=100;
function previewBulk(mode,one=false){bulkIds=one?[state.selected]:[...state.checked];bulkMode=mode;const objects=bulkIds.map(x=>obj(x)).filter(Boolean);let refs=all().filter(o=>objects.some(x=>x.kind==='model'&&x.id===o.ref));openModal('bulk',`<h2 id="dialog-title">${{copy:'复制配置',delete:'删除配置',move:'移动下游'}[mode]} · 影响预览</h2><div class="helper">${objects.map(o=>`${kindName(o.kind)} · ${esc(o.name)}`).join('<br>')}</div>${mode==='copy'?'<label class="toggle-label"><input type="checkbox" id="independent"> 创建独立空 memory 模型（默认共享；不复制运行数据）</label><p class="muted">复制网关的监听地址会清空，留在草稿中待补全。</p>':''}${mode==='delete'?`<div class="impact">删除配置不删除持久化文件或数据库内容。${refs.length?'模型被 '+refs.length+' 个入口引用，必须明确选择处理方式。':''}</div>${refs.length?`<label class="toggle-label"><input id="cascade" type="checkbox"> 连同 ${refs.length} 个引用下游一起删除</label>`:''}`:''}${mode==='move'?`<label>目标网关 <select id="move-target">${state.draft.gateways.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select></label><p class="muted">目标路由冲突将整次拒绝。</p>`:''}<footer>${button('取消','cancel')}${button('确认写入草稿','commit-bulk',mode==='delete'?'danger':'primary')}</footer>`);}
function remove(id){for(const g of state.draft.gateways){g.upstreams=g.upstreams.filter(o=>o.id!==id);g.downstreams=g.downstreams.filter(o=>o.id!==id);}state.draft.gateways=state.draft.gateways.filter(g=>g.id!==id);state.draft.models=state.draft.models.filter(m=>m.id!==id);}
function commitBulk(){if(bulkMode==='delete'){const removed=new Set(bulkIds);for(const id of bulkIds){const g=mutable(id);if(g?.kind==='gateway')[...g.upstreams,...g.downstreams].forEach(x=>removed.add(x.id));}const blocked=all().filter(x=>x.ref&&removed.has(x.ref)&&!removed.has(x.id));if(blocked.length&&!document.querySelector('#cascade')?.checked){toast('请选择引用处理方式，或取消后先迁移引用');return;}}const before=clone(state.draft),oldProblems=new Set(problems().map(p=>p.text));let independent=document.querySelector('#independent')?.checked,cascade=document.querySelector('#cascade')?.checked,target=document.querySelector('#move-target')?.value;for(const id of bulkIds){const o=obj(id);if(!o)continue;if(bulkMode==='delete'){const refs=all().filter(x=>x.ref===id&&!bulkIds.includes(x.id));if(cascade)refs.forEach(x=>remove(x.id));remove(id);}if(bulkMode==='copy'){let copy=clone(mutable(id));copy.id='copy'+(++uid);copy.name+='-copy';if(copy.kind==='model')state.draft.models.push(copy);if(copy.kind==='gateway'){copy.upstreams.forEach(x=>{x.id='copy'+(++uid);x.address='';});copy.downstreams.forEach(x=>{x.id='copy'+(++uid);});state.draft.gateways.push(copy);}if(copy.kind==='downstream'){let owner=mutable(o.gateway);const occupied=new Set(owner.downstreams.flatMap(d=>{try{return ids(d.slave_ids);}catch{return [];}}));let suggested=Array.from({length:256},(_,i)=>i).find(i=>!occupied.has(i));if(suggested===undefined){state.draft=before;toast('没有可分配的 Slave ID');return;}copy.slave_ids=String(suggested);owner.downstreams.push(copy);}if(independent){let children=copy.kind==='gateway'?copy.downstreams:[copy];const models=new Map();for(const d of children){if(d.ref){if(!models.has(d.ref)){let m=clone(mutable(d.ref));m.id='model'+(++uid);m.name+='-copy-'+uid;m.persistence='memory';m.path='';state.draft.models.push(m);models.set(d.ref,m.id);}d.ref=models.get(d.ref);}}}}if(bulkMode==='move'&&o.kind==='downstream'){let copy=clone(mutable(id));remove(id);mutable(target).downstreams.push(copy);}}
 const newErrors=problems().filter(p=>!oldProblems.has(p.text));if(newErrors.some(p=>bulkMode==='move'||p.text.includes('重叠')||p.text.includes('冲突'))){state.draft=before;toast('整次操作已拒绝：'+newErrors[0].text);return;}state.history.push(before);state.future=[];state.checked=[];state.selected='overview';closeModal();render();toast('已写入草稿，可撤销；尚未保存或应用。');}
let createTarget=null;
function newDialog(kind='gateway',target=null){
 if(!finishTransaction())return;
 createTarget=target;
 const model=kind==='model';
 const base=model?'新模拟模型':'新网关';
 const existing=model?state.draft.models:state.draft.gateways;
 let name=base,n=2;while(existing.some(x=>x.name===name))name=base+'-'+n++;
 openModal('new',`<h2 id="dialog-title">${target?'新建并引用模拟模型':model?'新建模拟模型':'新建网关'}</h2><div class="fields"><div class="field wide"><label for="new-name">${model?'模型名称':'网关名称'}</label><input id="new-name" value="${esc(name)}"></div>${model?`<div class="field wide"><label for="new-persistence">持久化方式</label><select id="new-persistence"><option value="memory">memory · 重启清空</option><option value="file">file · 文件存储</option><option value="mmap">mmap · 映射文件</option><option value="sql">sql · SQLite</option></select></div><div class="field wide" id="new-path-field" hidden><label for="new-path">持久化路径</label><input id="new-path" placeholder="例如 data/model.bin"><small>相对工程目录解析</small></div>`:''}</div><div class="helper">${model?'memory 数据只保留在运行进程中，重启会清空。持久化类型可在此选择或后续调整。':'创建后进入网关详情，分别添加上游和下游。未完成配置可以保留在草稿中。'}${target?`<p>确认后将绑定到 ${esc(obj(target)?.name)}，并返回当前下游。取消不会创建模型或改变引用。</p>`:''}</div><footer>${button('取消','cancel')}${button(target?'创建并引用':'创建到草稿','create','primary',false,`data-kind="${kind}"`)}</footer>`);
}
function createObject(kind){
 const name=document.querySelector('#new-name').value.trim();
 if(!name){toast('请输入名称');return;}
 const models=kind==='model',list=models?state.draft.models:state.draft.gateways;
 if(list.some(x=>x.name===name)){toast(models?'模拟模型名称已存在':'网关名称已存在');return;}
 const persistence=models?document.querySelector('#new-persistence').value:null;
 const path=models?document.querySelector('#new-path').value.trim():null;
 if(models&&persistence!=='memory'&&!path){toast('请输入持久化路径');document.querySelector('#new-path').focus();return;}
 const target=createTarget?mutable(createTarget):null;
 if(createTarget&&(!target||!['local','injector'].includes(target.type))){toast('目标下游已不适用，请取消后重新选择');return;}
 record();
 if(models){const m={id:'m'+(++uid),kind:'model',name,persistence,path:persistence==='memory'?'':path};state.draft.models.push(m);state.collapsed.models=false;if(target){target.ref=m.id;state.selected=target.id;}else state.selected=m.id;}
 else {const g={id:'g'+(++uid),kind:'gateway',name,upstreams:[],downstreams:[]};state.draft.gateways.push(g);state.selected=g.id;}
 state.query='';state.filter='all';closeModal();createTarget=null;render();
 toast(target?'已创建并引用模型，可一并撤销。':'已创建到草稿，尚未保存。');
}

async function action(key,e){switch(key){case'toggle-models':state.collapsed.models=!state.collapsed.models;render();break;case'toggle-gateway':state.collapsed[e.dataset.gateway]=!state.collapsed[e.dataset.gateway];render();break;case'state':state.showState=!state.showState;renderState();break;case'reset':scenario('clean');break;case'overview':state.group='gateway';navigate('overview');break;case'models':state.group='model';navigate('models');break;case'global':navigate('global');break;case'back':state.selected=state.back.pop()||'overview';render();break;case'visual':state.mode='visual';render();break;case'yaml':state.mode='yaml';render();break;case'diff':state.diff=!state.diff;render();break;case'diff-draft':state.diffTab='draft';render();break;case'diff-saved':state.diffTab='saved';render();break;case'undo':if(state.transaction)finishTransaction(true);else if(state.history.length){state.future.push(clone(state.draft));state.draft=state.history.pop();}render();break;case'redo':if(state.future.length){state.history.push(clone(state.draft));state.draft=state.future.pop();}render();break;case'finish':finishTransaction();render();break;case'cancel-edit':finishTransaction(true);render();break;case'save':save();break;case'save-apply':if(save())requestApply();break;case'apply':requestApply();break;case'cancel':closeModal();break;case'confirm-apply':{let fail=document.querySelector('#fail-next').checked;closeModal();state.runtime='应用中';render();setTimeout(()=>{if(fail){state.runtime='应用失败';toast('启动失败：监听地址被占用。');}else{state.running=clone(state.saved);state.lastGood=clone(state.running);state.runtime='运行中';toast('已应用，全部监听成功。');}render();},900);break;}case'rollback':state.running=clone(state.lastGood);state.runtime='运行中';render();toast('正在运行最近成功配置；文件与草稿保留。');break;case'conflict':showConflict();break;case'rebase':state.saved=clone(state.disk);state.conflict=false;closeModal();state.diff=true;state.diffTab='draft';render();toast('基线已更新。草稿保留，请核对磁盘改动并再次保存。');break;case'restore-draft':record();state.draft=clone(state.recovery);state.recovery=null;render();break;case'drop-recovery':state.recovery=null;render();break;case'clear-search':state.query='';state.filter='all';render();break;case'clear-checks':state.checked=[];render();break;case'copy-one':previewBulk('copy',true);break;case'delete-one':previewBulk('delete',true);break;case'batch-copy':previewBulk('copy');break;case'batch-delete':previewBulk('delete');break;case'batch-move':previewBulk('move');break;case'commit-bulk':commitBulk();break;case'new-gateway':newDialog('gateway');break;case'new-model':newDialog('model');break;case'new-reference':newDialog('model',state.selected);break;case'create':createObject(e.dataset.kind);break;case'open-model':navigate(obj(state.selected)?.ref);break;case'add-mapping':record();mutable(state.selected).mappings.push({source:'holding_registers',start:'16',count:'16',target:'input_registers',dest:'116'});render();break;case'remove-mapping':record();mutable(state.selected).mappings.splice(Number(e.dataset.index),1);render();break;case'add-upstream':case'add-downstream':{const g=mutable(state.selected);record();const o=clone(key==='add-upstream'?seed.gateways[0].upstreams[0]:seed.gateways[1].downstreams[0]);o.id='new'+(++uid);o.name=key==='add-upstream'?'新入口':'新下游';o.address='';if(key==='add-upstream')g.upstreams.push(o);else {o.slave_ids='';g.downstreams.push(o);}state.selected=o.id;render();break;}case'discard':openModal('discard',`<h2 id="dialog-title">放弃全部未保存修改？</h2><p>恢复到已保存文件，待应用配置保持不变。</p><footer>${button('取消','cancel')}${button('确认放弃','confirm-discard','danger')}</footer>`);break;case'confirm-discard':state.draft=clone(state.saved);state.history=[];state.future=[];state.transaction=null;closeModal();render();break;case'copy-yaml':try{await navigator.clipboard.writeText(yaml());toast('已复制草稿的 YAML 投影');}catch{toast('请在 YAML 页面选择文本复制');}break;case'issues':{const p=problems()[0];if(p)focusIssue(p.id,p.field);break;}case'stage':state.stage=Number(e.dataset.stage);state.selected='overview';render();break;case'stage-next':state.stage=(state.stage+1)%4;state.selected=state.stage===1?'d1':'overview';render();break;case'stage-back':state.stage=Math.max(0,state.stage-1);state.selected=state.stage===1?'d1':'overview';render();break;}}
function focusIssue(id,field){state.selected=id;state.mode='visual';if(variant==='C')state.stage=1;render();const el=document.getElementById(`field-${id}-${field}`);el?.scrollIntoView({block:'center'});el?.focus();}
document.addEventListener('click',e=>{const selected=e.target.closest('[data-select]');if(selected){navigate(selected.dataset.select);return;}const focused=e.target.closest('[data-focus]');if(focused){focusIssue(...focused.dataset.focus.split('|'));return;}const a=e.target.closest('[data-action]');if(a&&!a.disabled)action(a.dataset.action,a);});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='new-persistence'){document.querySelector('#new-path-field').hidden=t.value==='memory';}if(t.dataset.field){edit(t.dataset.id,t.dataset.field,t.type==='checkbox'?t.checked:t.value);if(t.dataset.field.endsWith('.source')){const i=t.dataset.field.split('.')[1],o=mutable(t.dataset.id);o.mappings[Number(i)].target=t.value==='coils'?'discrete_inputs':'input_registers';render();}}if(t.dataset.check){if(t.checked)state.checked.push(t.dataset.check);else state.checked=state.checked.filter(x=>x!==t.dataset.check);render();}if(t.id==='filter'){state.filter=t.value;render();}if(t.id==='group'){state.group=t.value;render();}if(t.id==='scenario')scenario(t.value);});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;const pos=e.target.selectionStart;render();document.querySelector('#search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(state.modal){if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){let controls=[...modalRoot.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}const editing=e.target.matches('input,textarea,select,[contenteditable]');if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='f'){e.preventDefault();document.querySelector('#search').focus();}if(!editing&&(e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();action(e.shiftKey?'redo':'undo');}});
fetch('/tokens.json').then(r=>r.json()).then(tokens=>{const root=document.documentElement,palette=Object.fromEntries(tokens.palette.map(p=>[p.name,p.value]));tokens.color.forEach(c=>root.style.setProperty('--'+c.name,palette[c.ref]));tokens.alpha.forEach(c=>root.style.setProperty('--'+c.name,c.value));tokens.radius.forEach(c=>root.style.setProperty('--radius-'+c.name,c.value+'px'));tokens.fontSize.forEach(c=>root.style.setProperty('--font-'+c.name,(Math.round(c.value*tokens.density['desktop-native']*2)/2)+'px'));render();});
